(()=>{'use strict';const search=document.getElementById('blog-search'),category=document.getElementById('blog-category'),cards=[...document.querySelectorAll('.blog-card')],count=document.getElementById('blog-count'),empty=document.getElementById('blog-empty');function filter(){const q=(search?.value||'').trim().toLowerCase(),c=category?.value||'all';let n=0;cards.forEach(card=>{const show=(!q||card.dataset.search.includes(q))&&(c==='all'||card.dataset.category===c);card.hidden=!show;if(show)n++;});if(count)count.textContent=`Showing ${n} article${n===1?'':'s'}`;if(empty)empty.hidden=n!==0;}search?.addEventListener('input',filter);category?.addEventListener('change',filter);})();
